/* remark-mermaid-blocks.mjs
 *
 * Remark plugin that converts fenced ```mermaid code blocks into
 * <img> tags pointing to pre-rendered SVG files.
 *
 * SVGs are generated by `npm run mermaid:render` (scripts/render-mermaid.mjs)
 * and stored in public/assets/diagrams/{slug}-{index}.svg.
 */

export default function remarkMermaidBlocks() {
  return function transformer(tree, file) {
    const filePath = (file?.history?.[0] || file?.path || '').replace(/\\/g, '/');

    if (!tree || !tree.children) return;

    let mermaidCount = 0;

    for (let i = 0; i < tree.children.length; i++) {
      const child = tree.children[i];

      if (child && child.type === 'code' && child.lang === 'mermaid') {
        mermaidCount++;
        const rawText = child.value || '';
        const slug = deriveSlug(filePath);
        const svgName = `${slug}-${mermaidCount}.svg`;
        const altText = generateAltText(rawText);

        // Use mdast 'image' node so rehype preserves attributes properly.
        // The class is added via data attribute; a rehype plugin converts it.
        tree.children[i] = {
          type: 'image',
          url: `/assets/diagrams/${svgName}`,
          alt: altText,
          data: {
            hProperties: {
              class: 'mermaid-diagram',
              loading: 'lazy',
              tabindex: '0',
              role: 'button',
              'aria-label': `Enlarge diagram: ${altText}`,
            },
          },
        };
      }
    }
  };
}

function deriveSlug(filePath) {
  // src/content/recipes/api/api-documentation-openapi.md → api-documentation-openapi
  // src/content/recipes/api/api-documentation-openapi.es.md → api-documentation-openapi-es
  const match = filePath.match(/src\/content\/[^/]+\/[^/]+\/(.+?)\.md$/);
  if (match) {
    return match[1].replace(/\.es$/, '-es');
  }
  return 'mermaid';
}

function generateAltText(code) {
  const lines = code.trim().split(/\r?\n/);

  // Allow an explicit accessible description via a `%% alt: ...` Mermaid comment.
  // If provided, use it as the full alt text without extra prefixes.
  const altComment = lines.find((line) => /^\s*%%\s*alt:\s*(.+)$/.test(line));
  if (altComment) {
    const match = altComment.match(/^\s*%%\s*alt:\s*(.+)$/);
    const alt = match?.[1]?.trim();
    if (alt) {
      return alt;
    }
  }

  // Skip leading Mermaid comments when looking for the diagram type and title.
  const nonCommentLines = lines.filter((line) => !/^\s*%%/.test(line));
  const firstLine = nonCommentLines[0] || 'diagram';
  const secondLine = nonCommentLines[1] || '';

  const desc = secondLine
    .replace(/^\s*[A-Z]\[/, '')
    .replace(/^\s*[A-Z]\{/, '')
    .replace(/["\]}].*$/, '')
    .trim();
  if (desc) {
    return `${firstLine.split(/\s/)[0]} diagram: ${desc}`;
  }
  return `Mermaid ${firstLine} diagram`;
}


